"""
Contract: perceive(observation_history) -> str must never raise, never return empty.
Outputs a concise (<2000 char) summary of decision-relevant features, including
delta from the previous state if available, to make both inverse and forward
prediction reliable.
"""

import json
from collections import Counter
from typing import Optional, List, Tuple, Dict

# ---------------------------------------------------------------------
#  Internal helpers
# ---------------------------------------------------------------------

def _parse_grid(obs: str) -> Optional[List[List[str]]]:
    """Extract the 2D colour grid as list[list[str]].

    Anchor on the generic '[[' / ']]' so it works regardless of the header text.
    Returns None on failure.
    """
    if not obs:
        return None
    start = obs.find("[[")
    end = obs.rfind("]]")
    if start == -1 or end == -1 or end < start:
        return None
    try:
        grid = json.loads(obs[start : end + 2])
    except Exception:
        return None
    if not grid or not isinstance(grid, list) or not isinstance(grid[0], list):
        return None
    return grid


def _determine_background(grid: List[List[str]]) -> str:
    """Return the most frequent colour in the grid (assumed background)."""
    flat = [cell for row in grid for cell in row]
    if not flat:
        return "black"
    count = Counter(flat)
    background, _ = count.most_common(1)[0]
    return background


def _non_bg_cells(grid: List[List[str]], background: str) -> List[Tuple[int, int, str]]:
    """Return sorted list of (row, col, colour) for cells not background."""
    cells = []
    for r, row in enumerate(grid):
        for c, colour in enumerate(row):
            if colour != background:
                cells.append((r, c, colour))
    cells.sort(key=lambda x: (x[0], x[1]))
    return cells


def _format_cells_compact(cells: List[Tuple[int, int, str]]) -> str:
    """Compact: (r,c,colour)(r,c,colour) ... No spaces."""
    return "".join(f"({r},{c},{colour})" for r, c, colour in cells)


def _format_delta(added: List[Tuple[int, int, str]],
                  removed: List[Tuple[int, int, str]],
                  changed: List[Tuple[int, int, str, str]]) -> str:
    """Return compact delta string, e.g. '+:(8,8,red)(9,8,red);-:(8,9,gray);~:(11,9,old->new)'."""
    parts = []
    if added:
        parts.append("+:" + _format_cells_compact(added))
    if removed:
        parts.append("-:" + _format_cells_compact(removed))
    if changed:
        chg_str = "".join(f"({r},{c},{old}->{new})" for r, c, old, new in changed)
        parts.append("~:" + chg_str)
    return ";".join(parts)


# ---------------------------------------------------------------------
#  Main perceive function
# ---------------------------------------------------------------------

def perceive(observation_history: list[str]) -> str:
    # Ensure we have at least one observation
    if not observation_history:
        return "empty"

    # Parse current grid
    cur_obs = observation_history[-1]
    cur_grid = _parse_grid(cur_obs)
    if cur_grid is None:
        return "no_grid"

    # Determine background
    background = _determine_background(cur_grid)
    rows = len(cur_grid)
    cols = len(cur_grid[0]) if rows > 0 else 0

    # Get current non-background cells
    cur_non_bg = _non_bg_cells(cur_grid, background)

    # Try to get previous state for delta
    prev_non_bg = None
    if len(observation_history) >= 2:
        prev_obs = observation_history[-2]
        prev_grid = _parse_grid(prev_obs)
        if prev_grid is not None:
            prev_bg = _determine_background(prev_grid)
            prev_non_bg = _non_bg_cells(prev_grid, prev_bg)

    # Compute deltas if possible
    added: List[Tuple[int, int, str]] = []
    removed: List[Tuple[int, int, str]] = []
    changed: List[Tuple[int, int, str, str]] = []  # (r,c,old,new)

    if prev_non_bg is not None:
        # Build dicts from (r,c) to colour for fast lookup
        prev_pos = {(r, c): colour for r, c, colour in prev_non_bg}
        cur_pos = {(r, c): colour for r, c, colour in cur_non_bg}

        # Handle same position with different colour -> changed
        for (r, c), cur_col in cur_pos.items():
            if (r, c) in prev_pos:
                prev_col = prev_pos[(r, c)]
                if prev_col != cur_col:
                    changed.append((r, c, prev_col, cur_col))
            else:
                added.append((r, c, cur_col))

        # Positions that were in previous but are not in current -> removed
        for (r, c), prev_col in prev_pos.items():
            if (r, c) not in cur_pos:
                removed.append((r, c, prev_col))

    # Build output parts (compact, no spaces)
    parts: List[str] = []
    parts.append(f"bg:{background};r{rows};c{cols}")

    if cur_non_bg:
        parts.append("cells:" + _format_cells_compact(cur_non_bg))
    else:
        parts.append("cells:empty")

    if prev_non_bg is not None:
        delta_str = _format_delta(added, removed, changed)
        if delta_str:
            parts.append("delta:" + delta_str)

    result = ";".join(parts)

    # Ensure length <2000 characters. If over, use a compact fallback that
    # preserves the full cell list but maybe with abbreviated color codes.
    # Here we simply fallback to a summary if result exceeds 1999 (should be rare).
    if len(result) > 1999:
        # Use one-letter codes for common colors to compress
        color_map = {
            "black": "k", "white": "w", "gray": "g", "grey": "g",
            "skyblue": "s", "lightblue": "l", "blue": "b", "darkblue": "d",
            "red": "r", "green": "n", "darkgreen": "dg", "limegreen": "lg",
            "gold": "go", "yellow": "y", "orange": "o", "brown": "br",
            "tan": "t", "pink": "p", "mediumpurple": "mp", "purple": "pu"
        }
        def short_col(c: str) -> str:
            return color_map.get(c, c[:3])  # fallback to first 3 chars

        bg_short = short_col(background)
        cells_short = "".join(f"({r},{c},{short_col(col)})" for r, c, col in cur_non_bg)

        parts2 = [f"bg:{bg_short};r{rows};c{cols}"]
        if cur_non_bg:
            parts2.append("cells:" + cells_short)
        else:
            parts2.append("cells:empty")
        # Add counts from delta if any
        if prev_non_bg is not None:
            dc = f"+{len(added)}-{len(removed)}~{len(changed)}"
            parts2.append("delcnt:" + dc)
        result = ";".join(parts2)
        # Final safety truncation – should not happen
        if len(result) > 1999:
            result = result[:1995] + "..."
    # Never return empty
    return result if result else "empty"
